# System prompt to steer the agent to be an expert researcher
import os
import uuid
from typing import Literal

from deepagents import create_deep_agent
from dotenv import load_dotenv
from langchain_core.globals import set_debug, set_verbose
from langchain_core.tools import tool
from langgraph.checkpoint.memory import MemorySaver
from tavily import TavilyClient

set_debug(True)
set_verbose(True)
load_dotenv()

tavily_client = TavilyClient(api_key=os.environ["TAVILY_API_KEY"])
config = {"configurable": {"thread_id": str(uuid.uuid4())}}


def internet_search(
    query: str,
    max_results: int = 5,
    topic: Literal["general", "news", "finance"] = "general",
    include_raw_content: bool = False,
):
    """Run a web search"""
    return tavily_client.search(
        query,
        max_results=max_results,
        include_raw_content=include_raw_content,
        topic=topic,
    )


@tool
def delete_file(path: str) -> str:
    """Delete a file from the filesystem."""
    return f"Deleted {path}"


@tool
def read_file(path: str) -> str:
    """Read a file from the filesystem."""
    return f"Contents of {path}"


@tool
def send_email(to: str, subject: str, body: str) -> str:
    """Send an email."""
    return f"Sent email to {to}"


@tool
def write_report(title: str, content: str) -> str:
    """Write a report."""
    return f"Wrote report: {title}"


research_instructions = """
You are an expert researcher. Your job is to conduct 
thorough research, and then write a polished report.
""".strip()


research_subagent = {
    "name": "research-agent",
    "description": "Used to research more in depth questions",
    "system_prompt": "You are a great researcher",
    "tools": [internet_search],
    # "model": "ollama:qwen3.5:397b-cloud",  # Optional override, defaults to main agent model
}

checkpointer = MemorySaver()

agent = create_deep_agent(
    model="ollama:qwen3.5:397b-cloud",
    system_prompt=research_instructions,
    tools=[
        delete_file,
        read_file,
        send_email,
        write_report,
    ],
    interrupt_on={
        "delete_file": True,
        "read_file": True,
        "send_email": {"allowed_decisions": ["approve", "reject"]},
        "write_report": {"allowed_decisions": ["approve", "reject"]},
    },
    subagents=[research_subagent],
    checkpointer=checkpointer,
)

result = agent.invoke(
    {
        "messages": [{"role": "user", "content": "대한민국 미래 경제 전망에 대해서 조사해주세요."}],
    },
    config=config,
)
print(result["messages"][-1].content)

